cypher:
MATCH (b:PlantItem {tag:'E-53-1'})
MATCH (u:Valve)-[:line_to*1..]->(b)
WITH DISTINCT b, u
WHERE NOT EXISTS {
  MATCH (x:Equipment)
  WHERE x <> u AND x <> b
    AND NOT EXISTS { (x)-[:line_to*1..]->(u) }
    AND NOT EXISTS { (u)-[:line_to*1..]->(x) }
    AND EXISTS { (x)-[:line_to*1..]->(b) }
}
RETURN DISTINCT u.tag AS valve
ORDER BY valve

